        if isinstance(window_seconds, bool) or not isinstance(window_seconds, (int, float)):
            raise ValueError("window_seconds must be a number (int or float), not bool")
        if window_seconds < 0:
            raise ValueError("window_seconds must be non-negative")

        self.window_seconds = float(window_seconds)
        self.processed = {} # event_id -> dict

    def _hash_payload(self, payload):
        # Ensure payload is serializable to JSON for hashing
        raw = json.dumps(payload, sort_keys=True)
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()

    def process(self, event_id, payload, handler, now=None):
        # Validate event_id
        if not isinstance(event_id, str) or not event_id:
            raise ValueError("event_id must be a non-empty string")

        # Validate handler
        if not callable(handler):
            raise ValueError("handler must be callable")

        # Validate now if provided
        if now is not None:
            if isinstance(now, bool) or not isinstance(now, (int, float)):
                raise ValueError("now must be a number (int or float) or None")
            if now < 0:
                raise ValueError("now must be non-negative")
            current_time = float(now)
        else:
            current_time = time.time()

        # Check for existing event
        if event_id in self.processed:
            stored_record = self.processed[event_id]

            # Check if the payload conflicts
            current_hash = self._hash_payload(payload)
            if current_hash != stored_record["payload_hash"]:
                raise ConflictingPayloadError(
                    f"Idempotency key '{event_id}' already exists with a different payload"
                )

